import{_ as t,o,c as s,a0 as a}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Keelhaven for restic users","description":"Keelhaven is a native macOS menu bar front end for restic. Exactly which restic commands it runs, how to connect a repository you already have, and what it deliberately leaves to the command line.","frontmatter":{"title":"Keelhaven for restic users","description":"Keelhaven is a native macOS menu bar front end for restic. Exactly which restic commands it runs, how to connect a repository you already have, and what it deliberately leaves to the command line."},"headers":[],"relativePath":"restic.md","filePath":"restic.md"}'),r={name:"restic.md"};function d(i,e,n,h,c,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="keelhaven-for-restic-users" tabindex="-1">Keelhaven for restic users <a class="header-anchor" href="#keelhaven-for-restic-users" aria-label="Permalink to &quot;Keelhaven for restic users&quot;">​</a></h1><p>Keelhaven is a front end, not a fork. It ships the stock restic binary (0.19.1), runs it as a child process, and writes ordinary restic repositories. Everything it does you could type yourself — it adds the schedule, the Keychain and the menu bar.</p><h2 id="what-it-runs" tabindex="-1">What it runs <a class="header-anchor" href="#what-it-runs" aria-label="Permalink to &quot;What it runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When</th><th>Command</th></tr></thead><tbody><tr><td>A new plan</td><td><code>restic init</code></td></tr><tr><td>Each scheduled run</td><td><code>restic backup --json --tag keelhaven &lt;folders&gt;</code></td></tr><tr><td>Retention, at most weekly, after a good backup</td><td><code>restic forget --prune --tag keelhaven --keep-…</code></td></tr><tr><td>Verification, weekly by default</td><td><code>restic check</code></td></tr><tr><td>Opening a snapshot to choose files</td><td><code>restic ls &lt;snapshot&gt; --json</code></td></tr><tr><td>Restore</td><td><code>restic restore &lt;snapshot&gt; --target &lt;new folder&gt;</code>, plus <code>--include &lt;path&gt;</code> for each file or folder you picked</td></tr><tr><td>A stale lock, when you ask</td><td><code>restic unlock</code> — never <code>--remove-all</code></td></tr></tbody></table><p>One restic process runs at a time, app-wide. The <code>--tag</code> on <code>forget</code> arrived in 0.9.2 — <em>Use a repository you already have</em>, below, says why it matters.</p><p>A snapshot is listed once, whole, and browsed from memory: opening the repository is the slow part of <code>ls</code>, so a call per folder would pay for it on every click. The paths handed to <code>--include</code> are escaped, so a file called <code>photo[1].jpg</code> is restored as itself and not as whatever the pattern matches.</p><p>The retention choices are presets over the keep flags:</p><table tabindex="0"><thead><tr><th>Choice</th><th>Flags</th></tr></thead><tbody><tr><td>Keep everything (the default)</td><td><code>forget</code> is never run</td></tr><tr><td>A year of history</td><td><code>--keep-last 3 --keep-daily 7 --keep-weekly 5 --keep-monthly 12</code></td></tr><tr><td>A month of history</td><td><code>--keep-last 3 --keep-daily 7 --keep-weekly 4</code></td></tr><tr><td>Keep a set number of backups</td><td><code>--keep-last N</code></td></tr></tbody></table><h2 id="where-the-secrets-are" tabindex="-1">Where the secrets are <a class="header-anchor" href="#where-the-secrets-are" aria-label="Permalink to &quot;Where the secrets are&quot;">​</a></h2><p>The repository password and any storage key live in the macOS Keychain. They reach restic through its environment — <code>RESTIC_PASSWORD</code>, <code>AWS_SECRET_ACCESS_KEY</code>, <code>RESTIC_REST_PASSWORD</code> — and never through its arguments or a file.</p><p>That environment is built from scratch: <code>PATH</code>, <code>HOME</code>, <code>TMPDIR</code> and <code>SSH_AUTH_SOCK</code>, plus the repository and its credentials. Nothing else from your session is passed on.</p><h2 id="use-a-repository-you-already-have" tabindex="-1">Use a repository you already have <a class="header-anchor" href="#use-a-repository-you-already-have" aria-label="Permalink to &quot;Use a repository you already have&quot;">​</a></h2><p>On the destination step open <strong>Advanced options</strong> and tick <strong>Connect to an existing repository at this destination</strong>. Keelhaven checks your password against it and creates nothing.</p><p>Snapshots made by other machines stay where they are, and the restore window lists them alongside Keelhaven&#39;s own.</p><p>Retention leaves them alone as well, from 0.9.2 on. There <code>forget</code> runs with <code>--tag keelhaven</code>, so it only ever considers snapshots Keelhaven made; anything the restic command line or another tool wrote stays until you prune it yourself.</p><p><strong>0.9.1 and earlier applied the policy to every snapshot in the repository.</strong> Update before you turn retention on for a repository that something else writes to.</p><p><strong>One repository, one retention choice.</strong> Every plan tags its snapshots the same way, so when two Keelhaven plans — or two Macs running Keelhaven — share a repository, whichever retention pass runs applies its policy to both. Give each plan a repository of its own, or set them all to the same choice.</p><h2 id="use-the-command-line-alongside-it" tabindex="-1">Use the command line alongside it <a class="header-anchor" href="#use-the-command-line-alongside-it" aria-label="Permalink to &quot;Use the command line alongside it&quot;">​</a></h2><p>The repository address is what you would expect:</p><table tabindex="0"><thead><tr><th>Destination</th><th>Address</th></tr></thead><tbody><tr><td>Folder or drive</td><td>the path itself</td></tr><tr><td>S3-compatible</td><td><code>s3:https://&lt;endpoint&gt;/&lt;bucket&gt;/&lt;prefix&gt;</code></td></tr><tr><td>SFTP</td><td><code>sftp:&lt;user&gt;@&lt;host&gt;:&lt;path&gt;</code></td></tr><tr><td>REST server</td><td><code>rest:http://&lt;host&gt;:8000/</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Restored</span></span></code></pre></div><p>restic&#39;s own locks keep the two from colliding.</p><h2 id="which-options-it-exposes" tabindex="-1">Which options it exposes <a class="header-anchor" href="#which-options-it-exposes" aria-label="Permalink to &quot;Which options it exposes&quot;">​</a></h2><p>There is no box for extra arguments, on purpose: <code>--quiet</code> or <code>--verbose</code> would break the JSON stream the progress bar reads, and <code>--no-lock</code> would defeat the one-run-at-a-time guard. The options people ask for are named settings instead:</p><table tabindex="0"><thead><tr><th>Setting</th><th>restic flag</th></tr></thead><tbody><tr><td>Exclude patterns</td><td><code>--exclude</code></td></tr><tr><td>Skip cache folders</td><td><code>--exclude-caches</code></td></tr><tr><td>Skip backups when nothing has changed</td><td><code>--skip-if-unchanged</code></td></tr><tr><td>Don&#39;t back up other disks mounted inside these folders</td><td><code>--one-file-system</code></td></tr><tr><td>Don&#39;t measure the backup first</td><td><code>--no-scan</code></td></tr><tr><td>Preview Backup</td><td><code>--dry-run</code></td></tr><tr><td>Upload limit</td><td><code>--limit-upload</code></td></tr><tr><td>Files read at once</td><td><code>--read-concurrency</code></td></tr><tr><td>Pack size</td><td><code>--pack-size</code></td></tr></tbody></table><p>Missing one you rely on? <a href="https://github.com/shenxianpeng/keelhaven/issues/45" target="_blank" rel="noreferrer">Say which, and why</a>.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><ul><li><strong>rclone backends.</strong> Google Drive, OneDrive and Dropbox are not supported; an rclone remote keeps its credentials outside the Keychain. The <a href="https://github.com/shenxianpeng/keelhaven/issues/53" target="_blank" rel="noreferrer">reasoning is here</a>.</li><li><strong><code>restic mount</code>.</strong> The Restore window opens a snapshot, searches it and restores files out of it; it does not mount one in Finder.</li><li><strong>rest-server beyond its defaults</strong> — <code>--private-repos</code>, <code>--append-only</code> or a self-signed certificate.</li></ul>`,28)])])}const y=t(r,[["render",d]]);export{u as __pageData,y as default};
